 insert into private.ielts_learning_tasks(code,version,title,skill,purpose,audio_path,audio_sha256,instructions,success_description,taxonomy_version_id,pilot_student,questions,content,review_record,content_sha256,requires_review) values('bh-ielts-targeted-listening-l16-v1','0.1.0','Listening Lesson 10 step 2 of 6: Expected or actual?','listening','guided_practice','targeted-listening-06/aea7a4367bfc74202825f682ccd28f1a2d07e403f2dc0a602800c4e650cde237/BH-TL06-L10A_v1.mp3','aea7a4367bfc74202825f682ccd28f1a2d07e403f2dc0a602800c4e650cde237','You will hear part of a lecture about the design of queues. Read LEARN FIRST and the worked example. Then listen to the first half of the lecture again and choose the correct letter, A, B, C or D. You may pause or replay.','The first number or idea you hear is often a prediction, an old plan or a rejected option. Wait for ''in fact'', ''but'', ''rather than'' or ''instead''.','ad250533-8582-4bc5-986b-32b0c9640a16','b30e9c28-96f1-4d34-83e9-9b28b4926f42','[{"id": "q1", "prompt": "What did the lecturer predict about the students'' guesses?", "accepted_answers": ["B"], "taxonomy_node_id": "59fbf038-1ceb-48b0-b905-b7f78a8076e3", "supporting_node_id": "19e4299c-70f4-4d30-8726-4416be272056", "options": [{"value": "A", "label": "A  They would be almost exactly right."}, {"value": "B", "label": "B  They would be about fifty per cent too long."}, {"value": "C", "label": "C  They would be about double the real wait."}, {"value": "D", "label": "D  They would be shorter than the real wait."}]}, {"id": "q2", "prompt": "How did the students check how long they had really queued?", "accepted_answers": ["D"], "taxonomy_node_id": "19e4299c-70f4-4d30-8726-4416be272056", "supporting_node_id": "59fbf038-1ceb-48b0-b905-b7f78a8076e3", "options": [{"value": "A", "label": "A  They checked the time on their phones."}, {"value": "B", "label": "B  They asked the canteen staff."}, {"value": "C", "label": "C  They used a stopwatch."}, {"value": "D", "label": "D  They looked at the times on their receipts."}]}, {"id": "q3", "prompt": "Why did the managers not install faster lifts?", "accepted_answers": ["A"], "taxonomy_node_id": "59fbf038-1ceb-48b0-b905-b7f78a8076e3", "supporting_node_id": "610d8325-5a22-4df9-beb0-aa512ff82374", "options": [{"value": "A", "label": "A  It would have cost too much."}, {"value": "B", "label": "B  Nobody had complained."}, {"value": "C", "label": "C  The building was too old."}, {"value": "D", "label": "D  The lifts were already fast."}]}, {"id": "q4", "prompt": "What happened after the mirrors were put in?", "accepted_answers": ["C"], "taxonomy_node_id": "19e4299c-70f4-4d30-8726-4416be272056", "supporting_node_id": "c36d6dc9-4848-4368-a60d-480b92f8c117", "options": [{"value": "A", "label": "A  People used the stairs instead."}, {"value": "B", "label": "B  More people complained."}, {"value": "C", "label": "C  Most of the complaints stopped."}, {"value": "D", "label": "D  The lifts became faster."}]}, {"id": "q5", "prompt": "What did many banks and post offices have in the past?", "accepted_answers": ["C"], "taxonomy_node_id": "59fbf038-1ceb-48b0-b905-b7f78a8076e3", "supporting_node_id": "19e4299c-70f4-4d30-8726-4416be272056", "options": [{"value": "A", "label": "A  one line for all counters"}, {"value": "B", "label": "B  an estimated waiting time"}, {"value": "C", "label": "C  a separate line for each counter"}, {"value": "D", "label": "D  a ticket machine"}]}, {"id": "q6", "prompt": "According to the lecturer, what is the effect of a single line on the average wait?", "accepted_answers": ["B"], "taxonomy_node_id": "59fbf038-1ceb-48b0-b905-b7f78a8076e3", "supporting_node_id": "472c05b5-8cc0-43b8-b300-ae5b769d7769", "options": [{"value": "A", "label": "A  It becomes much shorter."}, {"value": "B", "label": "B  It stays almost the same."}, {"value": "C", "label": "C  It becomes longer."}, {"value": "D", "label": "D  It is impossible to measure."}]}]'::jsonb,'{"scope": "Targeted IELTS listening exercise; not a full paper or an official IELTS recording.", "suggested_minutes": 8, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-listening-targeted-focus-v1", "passage": "LEARN FIRST: the first thing you hear may be wrong\n\nIn IELTS Listening, speakers often mention a wrong option first:\n- a prediction: ''I''d predicted ... but in fact ...''\n- a rejected idea: ''Rather than ... they ...'' / ''Instead of ...''\n- the usual case before the exception: ''usually ... but this time ...''\nThe answer is the one the speaker finally confirms.\n\nWORKED EXAMPLE\nYou hear: ''Rather than install faster lifts, which would have been expensive, managers put mirrors beside the lift doors.''\nFaster lifts are mentioned first, but ''rather than'' rejects them. The managers'' solution was mirrors.\n\nNow listen and answer six questions.", "focus": "Select relevant spoken information: reject predictions and rejected options that come before the real answer."}'::jsonb || jsonb_build_object('teacher_notes', '1 B, "I''d predicted that the guesses would be about fifty per cent too long". Double was the actual result, not the prediction.
2 D, "we compared their guesses with the times on their receipts".
3 A, "Rather than install faster lifts, which would have been expensive, managers put mirrors beside the lift doors."
4 C, "the complaints largely stopped, even though the lifts were no faster". ''Largely'' = mostly.
5 C, "Many banks and post offices once had a separate line for each counter." The single line is the newer solution.
6 B, "The average wait may be almost the same, but people consider the system fairer". The change is in how fair it feels.
Read each explanation, then listen to that part again and hear the proof yourself.

