 insert into private.ielts_learning_tasks(code,version,title,skill,purpose,audio_path,audio_sha256,instructions,success_description,taxonomy_version_id,pilot_student,questions,content,review_record,content_sha256,requires_review) values('bh-ielts-targeted-listening-l17-v1','0.1.0','Listening Lesson 10 step 3 of 6: Notes in different words','listening','guided_practice','targeted-listening-06/3e515f0aadea922305f57a1a18d7b48112dc885a16fa489535fdf43415f2d77e/BH-TL06-L10B_v1.mp3','3e515f0aadea922305f57a1a18d7b48112dc885a16fa489535fdf43415f2d77e','You will hear part of a lecture about the design of queues. Read LEARN FIRST and the worked example. Then listen to the second half of the lecture and complete the notes. Write ONE WORD ONLY for each answer. You may pause or replay.','The notes paraphrase the lecture. Predict the word type, listen for the same meaning, and write the exact word you hear, spelled correctly.','ad250533-8582-4bc5-986b-32b0c9640a16','b30e9c28-96f1-4d34-83e9-9b28b4926f42','[{"id": "q1", "prompt": "Explained delays: train passengers are more patient when the driver gives the ________", "accepted_answers": ["reason"], "taxonomy_node_id": "19e4299c-70f4-4d30-8726-4416be272056", "supporting_node_id": "1b02bd3d-3b53-4357-ad5b-3e31e3c5f5bd", "answer_format": "text"}, {"id": "q2", "prompt": "Stage of the process: a wait before a service begins feels ________ than a wait after it has started", "accepted_answers": ["longer"], "taxonomy_node_id": "19e4299c-70f4-4d30-8726-4416be272056", "supporting_node_id": "610d8325-5a22-4df9-beb0-aa512ff82374", "answer_format": "text"}, {"id": "q3", "prompt": "Company: talking to others is a natural ________", "accepted_answers": ["distraction"], "taxonomy_node_id": "19e4299c-70f4-4d30-8726-4416be272056", "supporting_node_id": "fe66c90a-e788-44f7-8caa-4e0019026729", "answer_format": "text"}, {"id": "q4", "prompt": "Some waiting areas arrange their ________ so that people can talk", "accepted_answers": ["seating"], "taxonomy_node_id": "19e4299c-70f4-4d30-8726-4416be272056", "supporting_node_id": "1b02bd3d-3b53-4357-ad5b-3e31e3c5f5bd", "answer_format": "text"}, {"id": "q5", "prompt": "Virtual queues: customers ________ when they arrive and are told when it is their turn", "accepted_answers": ["register"], "taxonomy_node_id": "19e4299c-70f4-4d30-8726-4416be272056", "supporting_node_id": "fe66c90a-e788-44f7-8caa-4e0019026729", "answer_format": "text"}, {"id": "q6", "prompt": "Next lecture: the same ideas applied in ________", "accepted_answers": ["hospitals"], "taxonomy_node_id": "19e4299c-70f4-4d30-8726-4416be272056", "supporting_node_id": "1b02bd3d-3b53-4357-ad5b-3e31e3c5f5bd", "answer_format": "text"}]'::jsonb,'{"scope": "Targeted IELTS listening exercise; not a full paper or an official IELTS recording.", "suggested_minutes": 8, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-listening-targeted-focus-v1", "passage": "LEARN FIRST: notes use different words\n\nIn note completion, the notes do not repeat the lecturer''s words. They paraphrase them.\n1. Before you listen, read the note and predict the word type (noun, verb, adjective ...).\n2. Listen for the MEANING of the note, not the same words.\n3. Write the word you hear. Check the spelling and the word limit.\n\nWORKED EXAMPLE\nNote: ''Uncertainty: theme parks show an ________ waiting time.''\nYou hear: ''many theme parks and call centres now display or announce an estimated waiting time.''\n''Show'' paraphrases ''display''. After ''an'' you need an adjective starting with a vowel sound. -> estimated\n\nNow listen and complete six notes.", "focus": "Identify specific spoken detail: complete paraphrased lecture notes with one exact word."}'::jsonb || jsonb_build_object('teacher_notes', '1 reason: "Passengers on a delayed train are far more patient when the driver gives the reason for the delay".
2 longer: "Waiting before a service begins feels longer than waiting once it has started."
3 distraction: "Conversation is a natural distraction". ''Talking to others'' paraphrases ''conversation''.
4 seating: "some waiting areas now arrange their seating so that people can talk more easily".
5 register: "customers register when they arrive and are then told when it''s their turn".
6 hospitals: "In the next lecture, we''ll look at how these ideas have been applied in hospitals". Write the plural you hear.
Read each explanation, then listen to that part again and hear the proof yourself.

